package br.com.sussmartcare.queue.adapters.in.rest; import br.com.sussmartcare.queue.application.*; import br.com.sussmartcare.queue.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1") public class QueueController { private final QueueApplicationService app; public QueueController(QueueApplicationService a){app=a;} public record EnterRequest(@NotNull UUID visitId,@NotNull UUID facilityId,@NotBlank String clinicalPriority){} public record LeaveRequest(@Min(1) long expectedReturnMinutes,@Min(0) long graceMinutes){} @PostMapping("/queue-entries") public ResponseEntity<QueueEntry> enter(@Valid @RequestBody EnterRequest r){return ResponseEntity.status(201).body(app.enter(r.visitId(),r.facilityId(),r.clinicalPriority()));}@GetMapping("/queue-entries/by-visit/{visitId}") public ResponseEntity<QueueEntry> byVisit(@PathVariable UUID visitId){try{return ResponseEntity.ok(app.getByVisit(visitId));}catch(IllegalArgumentException ex){return ResponseEntity.notFound().build();}} @PostMapping("/queue-entries/{id}/leave") public QueueEntry leave(@PathVariable UUID id,@Valid @RequestBody LeaveRequest r){return app.leave(id,r.expectedReturnMinutes(),r.graceMinutes());} @PostMapping("/queue-entries/{id}/return") public QueueEntry returned(@PathVariable UUID id){return app.returned(id);} @PostMapping("/queue-entries/{id}/call") public QueueEntry call(@PathVariable UUID id){return app.call(id);} @GetMapping("/queues/{facilityId}/view") public List<QueueApplicationService.QueueView> view(@PathVariable UUID facilityId){return app.view(facilityId);} @GetMapping("/queues/{facilityId}/public-view") public List<QueueApplicationService.QueuePublicView> publicView(@PathVariable UUID facilityId){return app.publicView(facilityId);} @GetMapping("/queues/{facilityId}/estimate") public WaitTimeEstimator.FacilityEstimate estimate(@PathVariable UUID facilityId){return app.facilityEstimate(facilityId);} }